    fn reader_enter_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(reader_guard)]
    fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) { 
        // Prove that the ranges_no_overlap invariant is preserved
        assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j ==>
            post.combiner[i].no_overlap_with(post.combiner[j]) by {

            // Case analysis based on whether i or j is the node_id that changed
            if i == node_id || j == node_id {
                // One of the nodes is the one that changed state

                // Let's handle the case where i == node_id
                if i == node_id {
                    // The state of node_id changed from Reading(Range) to Reading(Guard)
                    // Need to check that it still satisfies no_overlap_with constraints

                    let old_state = pre.combiner[i];
                    let new_state = post.combiner[i];

                    // Verify that the new state doesn't overlap with any other state
                    assert forall |other_node| post.combiner.contains_key(other_node) && other_node != i ==>
                        new_state.no_overlap_with(post.combiner[other_node]) by {

