                        assert(other_state == pre.combiner[other_node]);

                        // Since the old state satisfied no_overlap_with, we know:
                        assert(old_state.no_overlap_with(pre.combiner[other_node]));

                        // Now we need to show that new_state.no_overlap_with(other_state)
                        // Looking at the definition of no_overlap_with, we only care about Appending states

                        match new_state {
                            CombinerState::Reading(rs) => {
                                match rs {
