                                                // Based on definition: (cur_idx > cur) || (tail <= cur)  
                                                // where cur_idx/tail are from Appending, and cur is from Guard

                                                // This follows from the pre-state invariant and the fact that
                                                // the Guard's cur was within the pre-state bounds
                                            }
                                            _ => {}
                                        }
                                    }
                                    _ => {} // Other Reader states also return true
