            let pre_reader_state = pre.combiner[node_id].get_Reading_0();
            let post_reader_state = post.combiner[node_id].get_Reading_0();

            match pre_reader_state {
                ReaderState::Range{start, end, cur} => {
                    match post_reader_state {
                        ReaderState::Guard{start: start_post, end: end_post, cur: cur_post, val} => {
                            // These should be equal as per transition definition
                            assert(start_post == start);
                            assert(end_post == end);
                            assert(cur_post == cur);

                            // Verify the conditions for a valid Guard state:
                            // 1. Local version matches start
                            assert(post.local_versions[node_id] == pre.local_versions[node_id]);
                            assert(pre.reader_state_valid(node_id, pre_reader_state));
                            assert(pre.local_versions[node_id] == start);
                            assert(post.local_versions[node_id] == start);

                            // 2. Ordering constraints  
                            assert(start <= end);
                            assert((post.tail as int) - (post.buffer_size as int) <= end <= (post.tail as int));

                            // 3. Current position constraint
                            assert(start <= cur < end);

                            // 4. Entries up to and including cur must be alive
                            assert forall |i| start <= i <= cur implies log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
                                // From pre-state validity and the requirement in the transition
                                assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
                                // For i < cur: should hold by pre-state validity
                            };

                            // 5. Entries up to and including cur must exist in contents
                            assert forall |i| start <= i <= cur implies post.contents.contains_key(i) by {
                                // Should follow from pre-state validity
                                assert(pre.contents.contains_key(cur as int));
                            };

                            // 6. Value equality
                            assert(post.contents.contains_key(cur as int));
                            assert(post.contents[cur as int] === val);
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        } else {
            // This node didn't change state, so its validity follows from pre-state
            assert(pre.combiner.contains_key(nid));
            assert(pre.combiner[nid].is_Reading());
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid] == pre.combiner[nid]);
        }
    };
}

