#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Prove that the ranges_no_overlap invariant is preserved  
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // The transition only modifies combiner[node_id], leaving all others unchanged
        assert(post.combiner[i] == if i == node_id { post.combiner[node_id] } else { pre.combiner[i] });
        assert(post.combiner[j] == if j == node_id { post.combiner[node_id] } else { pre.combiner[j] });

        if i == node_id || j == node_id {
            // At least one of i,j is the node that was modified. Both can't be since i != j.
            // WLOG, suppose i is the changed node. Then:
            if i == node_id { // j remains unchanged
                let original_state = pre.combiner[node_id];
                let new_state = post.combiner[node_id]; 
                let other_state = post.combiner[j]; //= pre.combiner[j]

                // By pre-inductive hypothesis assumption:
                assert(pre.combiner[node_id].no_overlap_with(pre.combiner[j]));

                // Need to show: new_state.no_overlap_with(other_state)
                // But the transition preserves the shape of reader states - it only changes 
                // CombinerState::Reading(ReaderState::Range{...} to CombinerState::Reading(ReaderState::Guard{...}
                // According to no_overlap_with def, only CombinerState::Appending overlaps with Reader Guards
                match other_state {
                    CombinerState::Appending { cur_idx, tail } => {
                        // Need to show: (cur_idx > cur) || (tail <= cur)
                        // where cur comes from the reader state being in Guard form
                        match new_state {
                            CombinerState::Reading(ReaderState::Guard{cur, ..}) => {
                                // For the original range state, we would have needed:
                                // (cur_idx > cur_old) || (tail <= cur_old) 
                                // where cur_old was the cur value in the Range state before transitioning to Guard
                                // But cur_old == cur since the transition preserves cur
                                assert(true);
                            }
                            _ => {}
                        }       
                    }
                    _ => {
                        // Other combinations trivially satisfy no_overlap_with condition 
                        assert(new_state.no_overlap_with(other_state));
                    }
                }
            } else { // j == node_id, i remains unchanged
                // Symmetric argument as above
                let original_state = pre.combiner[node_id];
                let new_state = post.combiner[node_id]; //= post.combiner[j]
                let other_state = post.combiner[i]; //= pre.combiner[i]

                assert(pre.combiner[node_id].no_overlap_with(pre.combiner[i]));

                match other_state {
                    CombinerState::Appending { cur_idx, tail } => {
                        match new_state {
                            CombinerState::Reading(ReaderState::Guard{cur, ..}) => {
                                assert(true);
                            }
                            _ => {}
                        } 
                    }
                    _ => {
                        assert(new_state.no_overlap_with(other_state));
                    }
                }
            }
        } else {
            // Neither i nor j were affected, so relation is same as in pre-state
            assert(post.combiner[i] == pre.combiner[i]);
            assert(post.combiner[j] == pre.combiner[j]);
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j])); 
        }
    };

    // Prove that the all_reader_state_valid invariant is preserved
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid == node_id { 
            // Post-state has post.combiner[node_id] = CombinerState::Reading(ReaderState::Guard{start, end, cur, val}) 
            let ReaderState::Guard{start, end, cur, val} = post.combiner[node_id].get_Reading_0() by {
                // Guaranteed by construction
            };

            // Need to check validity conditions for ReaderState::Guard:
            // &&& self.local_versions[node_id] == start
            assert(post.local_versions[node_id] == pre.local_versions[node_id]);
            // From pre-state validity, we know that for the previous ReaderState::Range{start, end, cur}: 
            // self.local_versions[node_id] == start 
            // So we maintain this property.

            // &&& start <= end 
            // Preserved from pre-state since fields were copied

            // &&& (self.tail as int) - (self.buffer_size as int) <= end <= (self.tail as int)
            // Need to justify that end still respects bounds w.r.t. updated tail if it changed
            assert(post.tail >= pre.tail); // Typically tail increases, verify!

            // &&& start <= cur < end  
            // &&& (forall |i| start <= i <= cur ==> log_entry_is_alive(self.alive_bits, i, self.buffer_size))
            // &&& (forall |i| start <= i <= cur ==> self.contents.contains_key(i))
            // &&& self.contents.contains_key(cur as int)
            // &&& self.contents[cur as int] === val
            // These rely on explicit requirement checked in transition:
            assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
            assert(pre.contents.contains_key(cur as int)); // Given in preconditions
            assert(post.contents.contains_key(cur as int)); // Contents unchanged in this step
            assert(val === pre.contents[cur as int]); // How birds_eye val is defined
            assert(post.contents[cur as int] === val);
        } else {
            // Not changed, so validity inherited from pre-state
            assert(pre.combiner.contains_key(nid));  
            assert(pre.combiner[nid].is_Reading());
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid] == pre.combiner[nid]);
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        }
    };
}

