#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // In this transition:
    // 1. Remove combiner[node_id] = CombinerState::Reading(ReaderState::Range{ start, end, cur })
    // 2. Add    combiner[node_id] = CombinerState::Reading(ReaderState::Guard{ start, end, cur, val })
    // where val = pre.contents[cur]

    // Everything except combiner[node_id] remains unchanged:
    assert forall |i| i != node_id implies post.combiner[i] == pre.combiner[i] by {};
    assert(post.combiner[node_id] != pre.combiner[node_id]);

    // Prove that the ranges_no_overlap invariant is preserved  
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {

        if i == node_id || j == node_id {
            // Only one of them can be the modified node (since i != j)
            if i == node_id {
                // j is unchanged
                assert(post.combiner[j] == pre.combiner[j]);

                // By pre-inductive hypothesis, we know pre.combiner[node_id].no_overlap_with(pre.combiner[j]).
                // The transition only changes the reader state from Range to Guard, preserving start,end,cur.
                // According to the definition of no_overlap_with, 
                // CombinerState::Reading only fails to overlap with CombinerState::Appending when certain conditions hold.
                // Since the Range and Guard states have the same parameters (start, end, cur),
                // if pre.combiner[node_id].no_overlap_with(pre.combiner[j]) held, then 
                // post.combiner[node_id].no_overlap_with(post.combiner[j]) must also hold.
                assert(post.combiner[i].no_overlap_with(post.combiner[j]));
            } else { // j == node_id
                // i is unchanged 
                assert(post.combiner[i] == pre.combiner[i]); 
                assert(pre.combiner[i].no_overlap_with(pre.combiner[node_id]));
                assert(post.combiner[i].no_overlap_with(post.combiner[j]));
            }
        } else {
            // Both i,j are unchanged from pre-state
            assert(post.combiner[i] == pre.combiner[i]);
            assert(post.combiner[j] == pre.combiner[j]); 
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
            assert(post.combiner[i].no_overlap_with(post.combiner[j]));
        }
    };

    // Prove that the all_reader_state_valid invariant is preserved
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {

        if nid == node_id { 
            // Post-state has post.combiner[node_id] = CombinerState::Reading(ReaderState::Guard{start, end, cur, val}) 
            let reader_state = post.combiner[node_id].get_Reading_0();
            match reader_state {
                ReaderState::Guard{start, end, cur, val} => {
                    // From the transition, we know that pre.combiner[node_id] was 
                    // CombinerState::Reading(ReaderState::Range{start, end, cur}).

                    // And from the inductive assumption on pre-state:
                    assert(pre.reader_state_valid(node_id, ReaderState::Range{start, end, cur}));

                    // What does reader_state_valid say about ReaderState::Range?
                    // It requires several conditions including:
                    // self.local_versions[node_id] == start
                    // start <= end
                    // (self.tail as int) - (self.buffer_size as int) <= end <= (self.tail as int) 
                    // start <= cur <= end
                    // (forall |i| start <= i < cur ==> log_entry_is_alive(self.alive_bits, i, self.buffer_size))
                    // (forall |i| start <= i < cur ==> self.contents.contains_key(i))

                    // For ReaderState::Guard variant, it requires similar conditions, but with slight differences:
                    // start <= cur < end (strict inequality rather than <=)
                    // (forall |i| start <= i <= cur ==> ...) rather than i < cur

                    // Since post.local_versions == pre.local_versions and post.tail == pre.tail, 
                    // and alive_bits,content are also unchanged, most conditions carry over.

                    // We do have a special requirement in the transition:
                    // have alive_bits >= [ log_entry_idx(cur as int, pre.buffer_size) => log_entry_alive_value(cur as int, pre.buffer_size) ];
                    assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));

                    // Also from the transition birds_eye let val = pre.contents.index(cur as int);
                    assert(pre.contents.contains_key(cur as int));
                    assert(post.contents.contains_key(cur as int)); // contents unchanged  
                    assert(post.contents[cur as int] === val);
                }
                _ => {}
            }
        } else {
            // Not changed, so validity inherited from pre-state
            assert(pre.combiner.contains_key(nid));  
            assert(pre.combiner[nid].is_Reading());
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid] == pre.combiner[nid]);
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        }
    };
}

