#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) { 
    // The transition changes only combiner[node_id] from Reading(Range) to Reading(Guard)
    // with identical start,end,cur parameters. All other state components remain unchanged.

    // Establish basic facts about state correspondence
    assert forall |i| i != node_id implies post.combiner[i] == pre.combiner[i] by {};
    assert(post.contents === pre.contents);
    assert(post.alive_bits === pre.alive_bits);
    assert(post.local_versions === pre.local_versions);
    assert(post.tail == pre.tail);
    assert(post.buffer_size == pre.buffer_size);

    // Prove ranges_no_overlap invariant preservation
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {

        if i == node_id || j == node_id {
            // At least one of the indices refers to the modified combiner state
            if i == node_id && j == node_id {
                // Impossible since i != j
            } else if i == node_id {
                // combiner[i] = post.combiner[node_id] changed from Reading(Range) to Reading(Guard)
                // combiner[j] = post.combiner[j] = pre.combiner[j] remains unchanged

                // From pre-inductive hypothesis:
                assert(pre.combiner[node_id].no_overlap_with(pre.combiner[j])); 

                // Analyze what no_overlap_with means for CombinerState::Reading vs others:
                match pre.combiner[j] {
                    CombinerState::Appending { cur_idx, tail } => {
                        // For Reading(Range{start, end, cur}): no_overlap_with(Appending{cur_idx, tail}) requires:
                        // (cur_idx > cur) || (tail <= cur)
                        // 
                        // For Reading(Guard{start, end, cur, ..}): no_overlap_with(Appending{cur_idx, tail}) requires:
                        // (cur_idx > cur) || (tail <= cur) [same condition!]
                        //
                        // Since start,end,cur are preserved by the transition, and the condition
                        // depends only on these values, it carries forward.
                    }
                    _ => {
                        // All other combinations return true automatically
                    }
                }
            } else { // j == node_id, i != node_id
                // combiner[i] = post.combiner[i] = pre.combiner[i] remains unchanged  
                // combiner[j] = post.combiner[node_id] changed from Reading(Range) to Reading(Guard)

                // From pre-inductive hypothesis:
                assert(pre.combiner[i].no_overlap_with(pre.combiner[node_id]));

                match pre.combiner[i] {
                    CombinerState::Appending { cur_idx, tail } => {
                        // For Appending{cur_idx, tail} vs Reading(Range{start, end, cur}): 
                        // requires (cur_idx > cur) || (tail <= cur)
                        //
                        // For Appending{cur_idx, tail} vs Reading(Guard{..., cur, ..}): 
                        // requires (cur_idx > cur) || (tail <= cur) [same!]
                    }
                    _ => {
                        // Other combinations return true automatically  
                    }
                }
            }
        } else {
            // Neither i nor j refer to the modified node_id
            assert(post.combiner[i] == pre.combiner[i]);
            assert(post.combiner[j] == pre.combiner[j]);
            // Pre-inductive hypothesis gives us:
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        }
    };

    // Prove all_reader_state_valid invariant preservation  
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {

        if nid == node_id {
            // This combiner state changed from Reading(Range) to Reading(Guard)
            let post_reader_state = post.combiner[node_id].get_Reading_0();
            match post_reader_state {
                ReaderState::Guard{start, end, cur, val} => {
                    // The pre-state had: Reading(Range{start, end, cur})
                    // From pre-inductive hypothesis and transition requirements:
                    assert(pre.reader_state_valid(node_id, ReaderState::Range{start, end, cur}));

                    // Transition explicitly requires this condition (have alive_bits >= [...]): 
                    assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));

                    // Transition defines val via birds_eye let val = pre.contents.index(cur as int);
                    // This means pre.contents.contains_key(cur as int) must hold
                    assert(pre.contents.contains_key(cur as int));
                    assert(post.contents.contains_key(cur as int)); // contents unchanged
                    assert(post.contents[cur as int] === val); // by definition of birds_eye

                    // Verify each condition required for ReaderState::Guard validity:
                    // &&& self.local_versions[node_id] == start
                    assert(post.local_versions[node_id] == pre.local_versions[node_id]);

                    // &&& start <= end
                    // &&& (self.tail as int) - (self.buffer_size as int) <= end <= (self.tail as int)
                    // These are inherited from pre-state validity

                    // &&& start <= cur < end
                    // pre-state: start <= cur <= end. Transition requires cur < end, so we get strict inequality

                    // &&& (forall |i| start <= i <= cur ==> log_entry_is_alive(...))
                    assert forall |i| start <= i <= cur implies log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
                        if i < cur {
                            // Pre-condition for Range required start <= i < cur ==> log_entry_is_alive
                        } else {
                            // i == cur: We have the explicit condition established above
                            assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
                        }
                    };

                    // &&& (forall |i| start <= i <= cur ==> self.contents.contains_key(i))  
                    assert forall |i| start <= i <= cur implies post.contents.contains_key(i) by {
                        if i < cur {
                            // Pre-condition for Range required start <= i < cur ==> contents.contains_key(i)
                        } else {
                            // i == cur: Established above via transition definition
                            assert(post.contents.contains_key(cur as int));
                        }  
                    };
                    // &&& self.contents.contains_key(cur as int) - established above
                    // &&& self.contents[cur as int] === val - established above
                }
                _ => {}
            }
        } else {
            // Combiner state unchanged, inherits validity directly
            assert(pre.combiner.contains_key(nid));
            assert(pre.combiner[nid].is_Reading());
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid] == pre.combiner[nid]);
        }
    };
}

