                            // i == cur: Requirement explicitly checked in transition:
                            // have alive_bits >= [ log_entry_idx(cur, buffer_size) => log_entry_alive_value(cur, buffer_size) ];
                            assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
                        }
                    };

                    // 6. Entries up to and including cur must be in contents
                    assert forall |i| start <= i <= cur implies post.contents.contains_key(i) by {
                        if i < cur {
                            // Was required in pre-state's Range condition (start <= i < cur) 
                        } else {
                            // i == cur: Transition defines val = pre.contents.index(cur), so contents must have cur key
                            assert(pre.contents.contains_key(cur as int));
                            // Contents unchanged in this transition
                            assert(post.contents.contains_key(cur as int));
                        }
                    };

                    // 7. Value correctness: post.contents[cur] === val
                    assert(val === pre.contents[cur as int]); // birds_eye definition
                    assert(post.contents[cur as int] === val); // contents unchanged
                }
                _ => {}
            }
        } else {
            // Unchanged state inherits validity from pre-state
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid] == pre.combiner[nid]);
        }
    };
}

