#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) { 
    // Establish correspondence: only combiner[node_id] has changed.
    assert(forall|i: NodeId| #[trigger] post.combiner.contains_key(i) && i != node_id ==> post.combiner[i] == pre.combiner[i]);
    assert(post.contents === pre.contents);
    assert(post.alive_bits === pre.alive_bits);
    assert(post.local_versions === pre.local_versions);
    assert(post.tail == pre.tail);
    assert(post.buffer_size == pre.buffer_size);

    // From the transition definition:  
    // remove combiner -= [ node_id => let CombinerState::Reading( ReaderState::Range{ start, end, cur }) ]
    // have alive_bits >= [ log_entry_idx(cur, pre.buffer_size) => log_entry_alive_value(cur, pre.buffer_size) ]
    // birds_eye let val = pre.contents.index(cur as int);
    // add combiner += [ node_id => CombinerState::Reading( ReaderState::Guard{ start, end, cur, val }) ]
    // require(cur < end);

    // Prove ranges_no_overlap (invariant violation was here):
    assert(forall|i: NodeId, j: NodeId| 
           post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j ==> 
           post.combiner[i].no_overlap_with(post.combiner[j])) by {

        assert(forall|i, j| i == node_id || j == node_id || (i != node_id && j != node_id)) by {}; 

        assert forall |i: NodeId, j: NodeId| 
            post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j 
            implies post.combiner[i].no_overlap_with(post.combiner[j]) by {

            if i != node_id && j != node_id {
                // Both unchanged from pre-state
                assert(post.combiner[i] == pre.combiner[i]); 
                assert(post.combiner[j] == pre.combiner[j]);
                // By the pre-inductive hypothesis and invariant satisfaction:
                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
            } else if i == node_id {
                // Only i changed, j is same, i != j so j != node_id
                assert(post.combiner[j] == pre.combiner[j]);
                // Pre-inductive hyp tells us pre.combiner[node_id].no_overlap_with(pre.combiner[j])
                // i.e. pre.combiner[i].no_overlap_with(pre.combiner[j])
                // The transition replaces Reading(Range{...params...}) with Reading(Guard{...same_params...})
                // The parameters (start,end,cur) are preserved. According to the definition of no_overlap_with,
                // for Reading vs Appending comparison, only cur matters: CombinerState::Reading(ReaderState::Guard{cur,..})
                // vs CombinerState::Appending{cur_idx,tail} requires (cur_idx > cur) || (tail <= cur) 
            } else { // j == node_id, i != node_id
                // Only j changed, i is same
                assert(post.combiner[i] == pre.combiner[i]);
                // Pre-inductive hyp tells us pre.combiner[i].no_overlap_with(pre.combiner[node_id])
                // After transition becomes post.combiner[i].no_overlap_with(post.combiner[node_id])
                // Transition changed node_id's state from Reading(Range{params}) to Reading(Guard{same_params})
            }
        }
    };

    // Prove all_reader_state_valid (invariant violation was here):
    assert(forall|n: NodeId| #[trigger] post.combiner.contains_key(n) && post.combiner[n].is_Reading() ==> 
           post.reader_state_valid(n, post.combiner[n].get_Reading_0())) by {

