// SPDX-License-Identifier: Apache-2.0 OR MIT

fn main() {}

#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use verus_state_machines_macros::*;
use vstd::prelude::*;

verus! {

tokenized_state_machine! { TestMachine {
    fields {
        #[sharding(map)]
        pub data: Map<int, int>,
    }

    init!{
        initialize() {
            init data = Map::empty();
        }  
    }

    transition!{
        add_element(key: int, value: int) {
           add data += [ key => value ];
        }
    }

    #[inductive(add_element)]
    fn add_element_inductive(pre: Self, post: Self, key: int, value: int) {
        assert(post.data.contains_key(key));
        assert(post.data[key] == value);
    }
}}

} // verus!
